def list_tasks(task_type=None, enabled=None, status=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0219000" if __import__("os").path.isdir("./environment_mix/0219000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    status_code = "ok"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _dt(x):
        if x is None:
            return None
        if isinstance(x, datetime.datetime):
            return x if x.tzinfo else x.replace(tzinfo=datetime.timezone.utc)
        if isinstance(x, str):
            try:
                s = x
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _encode_cursor(payload: dict) -> str:
        raw = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur: str):
        if not isinstance(cur, str) or not cur:
            return None
        try:
            pad = "=" * (-len(cur) % 4)
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            return obj if isinstance(obj, dict) else None
        except Exception:
            return None

    def _log(endpoint, status_code, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _now_iso()
        latency_ms = int((time.time() - t0) * 1000)
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "credential_id": None,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": now
        })
        _save("request_logs.json", logs)

    # Validation
    allowed_task_types = {"command", "api", "ai", "reminder"}
    allowed_status = {"active", "disabled", "completed", "deleted"}
    allowed_sort_by = {"created_at", "updated_at", "next_run_at", "last_run_at", "name"}
    allowed_sort_order = {"asc", "desc"}

    if task_type is not None and (not isinstance(task_type, str) or task_type not in allowed_task_types):
        status_code = "error"
        out = _err("VALIDATION_ERROR", "Invalid task_type.", allowed=list(sorted(allowed_task_types)))
        _log("list_tasks", status_code, out["error"]["code"])
        return out
    if enabled is not None and not isinstance(enabled, bool):
        status_code = "error"
        out = _err("VALIDATION_ERROR", "enabled must be a boolean.")
        _log("list_tasks", status_code, out["error"]["code"])
        return out
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        status_code = "error"
        out = _err("VALIDATION_ERROR", "Invalid status.", allowed=list(sorted(allowed_status)))
        _log("list_tasks", status_code, out["error"]["code"])
        return out
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        status_code = "error"
        out = _err("VALIDATION_ERROR", "limit must be an integer in range 1..200.")
        _log("list_tasks", status_code, out["error"]["code"])
        return out
    if cursor is not None and not isinstance(cursor, str):
        status_code = "error"
        out = _err("VALIDATION_ERROR", "cursor must be a string.")
        _log("list_tasks", status_code, out["error"]["code"])
        return out
    if sort_by is None:
        sort_by = "created_at"
    if not isinstance(sort_by, str) or sort_by not in allowed_sort_by:
        status_code = "error"
        out = _err("VALIDATION_ERROR", "Invalid sort_by.", allowed=list(sorted(allowed_sort_by)))
        _log("list_tasks", status_code, out["error"]["code"])
        return out
    if sort_order is None:
        sort_order = "asc"
    if not isinstance(sort_order, str) or sort_order not in allowed_sort_order:
        status_code = "error"
        out = _err("VALIDATION_ERROR", "Invalid sort_order.", allowed=list(sorted(allowed_sort_order)))
        _log("list_tasks", status_code, out["error"]["code"])
        return out

    cur = _decode_cursor(cursor) if cursor else None
    if cursor and cur is None:
        status_code = "error"
        out = _err("VALIDATION_ERROR", "Invalid cursor.")
        _log("list_tasks", status_code, out["error"]["code"])
        return out

    tasks = _load("scheduler_tasks.json")
    if not isinstance(tasks, list):
        tasks = []

    # Business rule: list excludes deleted by default
    filtered = []
    for r in tasks:
        if not isinstance(r, dict):
            continue
        if r.get("status") == "deleted":
            continue
        if task_type is not None and r.get("task_type") != task_type:
            continue
        if enabled is not None and r.get("enabled") is not enabled:
            continue
        if status is not None and r.get("status") != status:
            continue
        filtered.append(r)

    reverse = (sort_order == "desc")

    def _sort_key(r):
        v = r.get(sort_by)
        if sort_by in ("created_at", "updated_at", "next_run_at", "last_run_at"):
            d = _dt(v)
            # Treat None as far future for asc, far past for desc (so Nones sort last for asc, first for desc)
            if d is None:
                return datetime.datetime.max.replace(tzinfo=datetime.timezone.utc) if not reverse else datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            return d
        if sort_by == "name":
            return (v or "").casefold()
        return v

    # Secondary tie-breaker by id for stable pagination
    filtered.sort(key=lambda r: (_sort_key(r), r.get("id", "")), reverse=reverse)

    start = 0
    if cur:
        if cur.get("sort_by") != sort_by or cur.get("sort_order") != sort_order:
            status_code = "error"
            out = _err("VALIDATION_ERROR", "Cursor sort parameters do not match request.")
            _log("list_tasks", status_code, out["error"]["code"])
            return out
        last_id = cur.get("last_id")
        last_val = cur.get("last_val")
        # Find first item after cursor
        def _cmp_after(r):
            rid = r.get("id", "")
            sval = _sort_key(r)
            # Reconstruct cursor value for comparison
            if sort_by in ("created_at", "updated_at", "next_run_at", "last_run_at"):
                cv = _dt(last_val)
                rv = sval
                if cv is None:
                    cv = datetime.datetime.max.replace(tzinfo=datetime.timezone.utc) if sort_order == "asc" else datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
                if rv is None:
                    rv = datetime.datetime.max.replace(tzinfo=datetime.timezone.utc) if sort_order == "asc" else datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
                if sort_order == "asc":
                    return (rv, rid) > (cv, last_id)
                else:
                    return (rv, rid) < (cv, last_id)
            else:
                cv = last_val
                rv = sval
                if sort_order == "asc":
                    return (rv, rid) > (cv, last_id)
                else:
                    return (rv, rid) < (cv, last_id)

        found = False
        for i, r in enumerate(filtered):
            if _cmp_after(r):
                start = i
                found = True
                break
        if not found:
            start = len(filtered)

    page = filtered[start:start + limit]
    has_more = (start + limit) < len(filtered)

    next_cursor = None
    if has_more and page:
        last = page[-1]
        last_val = last.get(sort_by)
        next_cursor = _encode_cursor({
            "sort_by": sort_by,
            "sort_order": sort_order,
            "last_id": last.get("id"),
            "last_val": last_val
        })

    out = {
        "items": page,
        "total": len(filtered),
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "sort_by": sort_by,
        "sort_order": sort_order
    }
    _log("list_tasks", status_code, None)
    return out

def get_task(task_id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0219000" if __import__("os").path.isdir("./environment_mix/0219000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    status_code = "ok"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(endpoint, status_code, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _now_iso()
        latency_ms = int((time.time() - t0) * 1000)
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "credential_id": None,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": now
        })
        _save("request_logs.json", logs)

    if not isinstance(task_id, str) or not task_id.strip():
        status_code = "error"
        out = _err("VALIDATION_ERROR", "task_id must be a non-empty string.")
        _log("get_task", status_code, out["error"]["code"])
        return out

    tasks = _load("scheduler_tasks.json")
    if not isinstance(tasks, list):
        tasks = []
    row = None
    for r in tasks:
        if isinstance(r, dict) and r.get("id") == task_id and r.get("status") != "deleted":
            row = r
            break

    if row is None:
        status_code = "error"
        out = _err("NOT_FOUND", "Task not found.", task_id=task_id)
        _log("get_task", status_code, out["error"]["code"])
        return out

    out = {"task": row}
    _log("get_task", status_code, None)
    return out

def add_command_task(name, schedule, command, description=None, enabled=None, do_only_once=None, **_extra):
    import json, os, datetime, time, uuid, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0219000" if __import__("os").path.isdir("./environment_mix/0219000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "add_command_task"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat()
        return None

    def _load_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _write_log(status, error_code=None, message=None, credential_id=None):
        logs = _load_logs()
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": f"req_{int(time.time()*1000)}_{uuid.uuid4().hex[:8]}",
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": _now().isoformat(),
        }
        if message is not None:
            row["message"] = message
        logs.append(row)
        _save("request_logs.json", logs)

    def _nonempty_str(v):
        return isinstance(v, str) and v.strip() != ""

    def _validate_schedule(expr):
        # Supported:
        #  - "cron <min> <hour> <dom> <month> <dow>" (5-field)
        #  - "interval <n> <unit>" unit: second(s)/minute(s)/hour(s)/day(s)
        if not isinstance(expr, str):
            return _err("VALIDATION_ERROR", "schedule must be a string", field="schedule")
        s = expr.strip()
        if not s:
            return _err("VALIDATION_ERROR", "schedule must be a non-empty string", field="schedule")

        m = re.match(r"^\s*interval\s+(\d+)\s*(seconds|second|minutes|minute|hours|hour|days|day)\s*$", s, re.I)
        if m:
            n = int(m.group(1))
            if n <= 0:
                return _err("VALIDATION_ERROR", "interval must be a positive integer", field="schedule")
            return {"type": "interval", "n": n, "unit": m.group(2).lower()}

        m = re.match(r"^\s*cron\s+(.+)\s*$", s, re.I)
        if m:
            fields = m.group(1).split()
            if len(fields) != 5:
                return _err("VALIDATION_ERROR", "cron schedule must have 5 fields: min hour dom month dow", field="schedule")
            minute, hour, dom, month, dow = fields

            def _in_range(token, lo, hi):
                # Accept "*", "MON", "1-5", "*/5", "0,15,30", etc. Keep conservative but allow typical cron tokens.
                if token == "*":
                    return True
                # allow names for dow/month
                if re.fullmatch(r"[A-Za-z]{3}", token):
                    return True
                # allow comma-separated of basic tokens
                parts = token.split(",")
                for p in parts:
                    p = p.strip()
                    if not p:
                        return False
                    if p == "*":
                        continue
                    if re.fullmatch(r"\*/\d+", p):
                        step = int(p.split("/")[1])
                        if step <= 0:
                            return False
                        continue
                    if re.fullmatch(r"\d+-\d+", p):
                        a, b = p.split("-")
                        a = int(a)
                        b = int(b)
                        if a > b or a < lo or b > hi:
                            return False
                        continue
                    if re.fullmatch(r"\d+", p):
                        v = int(p)
                        if v < lo or v > hi:
                            return False
                        continue
                    return False
                return True

            # Validate numeric ranges where applicable; allow names for dow/month by letting _in_range accept 3-letter.
            if not _in_range(minute, 0, 59):
                return _err("VALIDATION_ERROR", "invalid cron minute field", field="schedule")
            if not _in_range(hour, 0, 23):
                return _err("VALIDATION_ERROR", "invalid cron hour field", field="schedule")
            if not _in_range(dom, 1, 31) and dom != "*":
                return _err("VALIDATION_ERROR", "invalid cron day-of-month field", field="schedule")
            if not _in_range(month, 1, 12):
                return _err("VALIDATION_ERROR", "invalid cron month field", field="schedule")
            # DOW: allow 0-7 plus names
            if not _in_range(dow, 0, 7):
                return _err("VALIDATION_ERROR", "invalid cron day-of-week field", field="schedule")

            return {"type": "cron", "fields": fields}

        return _err("VALIDATION_ERROR", "schedule must start with 'cron' or 'interval'", field="schedule")

    def _compute_next_run(expr, parsed, tz="UTC"):
        # Best-effort next-run computation. If cannot compute, return None (but only after schedule validated).
        now = _now()
        if not parsed:
            return None
        if parsed.get("type") == "interval":
            n = parsed["n"]
            unit = parsed["unit"]
            if unit.endswith("s"):
                unit = unit[:-1]
            delta = None
            if unit == "second":
                delta = datetime.timedelta(seconds=n)
            elif unit == "minute":
                delta = datetime.timedelta(minutes=n)
            elif unit == "hour":
                delta = datetime.timedelta(hours=n)
            elif unit == "day":
                delta = datetime.timedelta(days=n)
            else:
                return None
            return (now + delta).isoformat()

        if parsed.get("type") == "cron":
            # Minimal cron next run: attempt to compute for simple numeric minute/hour with wildcard dom/month/dow.
            # If complex, return None to avoid incorrect scheduling.
            minute, hour, dom, month, dow = parsed["fields"]

            def _is_simple_num(tok):
                return re.fullmatch(r"\d+", tok or "") is not None

            if _is_simple_num(minute) and _is_simple_num(hour) and dom == "*" and month == "*" and dow == "*":
                m = int(minute)
                h = int(hour)
                candidate = now.replace(second=0, microsecond=0)
                candidate = candidate.replace(hour=h, minute=m)
                if candidate <= now:
                    candidate = candidate + datetime.timedelta(days=1)
                return candidate.isoformat()

            return None

        return None

    # ---------- Validation ----------
    if not _nonempty_str(name):
        _write_log("error", "VALIDATION_ERROR", "name must be a non-empty string")
        return _err("VALIDATION_ERROR", "name must be a non-empty string", field="name")

    if not _nonempty_str(schedule):
        _write_log("error", "VALIDATION_ERROR", "schedule must be a non-empty string")
        return _err("VALIDATION_ERROR", "schedule must be a non-empty string", field="schedule")

    if not _nonempty_str(command):
        _write_log("error", "VALIDATION_ERROR", "command must be a non-empty string")
        return _err("VALIDATION_ERROR", "command must be a non-empty string", field="command")

    if description is not None and not isinstance(description, str):
        _write_log("error", "VALIDATION_ERROR", "description must be a string or null")
        return _err("VALIDATION_ERROR", "description must be a string or null", field="description")

    if enabled is None:
        enabled = True
    if do_only_once is None:
        do_only_once = True

    if not isinstance(enabled, bool):
        _write_log("error", "VALIDATION_ERROR", "enabled must be a boolean")
        return _err("VALIDATION_ERROR", "enabled must be a boolean", field="enabled")
    if not isinstance(do_only_once, bool):
        _write_log("error", "VALIDATION_ERROR", "do_only_once must be a boolean")
        return _err("VALIDATION_ERROR", "do_only_once must be a boolean", field="do_only_once")

    parsed = _validate_schedule(schedule)
    if isinstance(parsed, dict) and "error" in parsed:
        _write_log("error", parsed["error"]["code"], parsed["error"]["message"])
        return parsed

    # ---------- Load data ----------
    tasks = _load("scheduler_tasks.json")
    if isinstance(tasks, dict) and "rows" in tasks:
        # guard against accidental metadata object; treat as empty because real store is list of rows
        tasks = []
    if not isinstance(tasks, list):
        tasks = []

    # Unique(name) WHERE status <> 'deleted'
    name_norm = name.strip().lower()
    for t in tasks:
        try:
            if isinstance(t, dict) and t.get("status") != "deleted" and isinstance(t.get("name"), str):
                if t["name"].strip().lower() == name_norm:
                    _write_log("error", "CONFLICT", "A task with the same name already exists (unique(name) WHERE status <> 'deleted').")
                    return _err(
                        "CONFLICT",
                        "A task with the same name already exists (unique(name) WHERE status <> 'deleted').",
                        rule="unique(name) WHERE status <> 'deleted'",
                    )
        except Exception:
            # do not fail on a single bad row; continue scanning
            continue

    # Enforce enabled/status coupling
    status = "active" if enabled else "disabled"

    # type consistency (command task requires command; forbids api/prompt/reminder fields)
    # command is present by validation; ensure incompatible fields are NULL
    now_iso = _now().isoformat()

    # Compute next_run_at (must be NULL if disabled/completed/deleted)
    tz = "UTC"
    runtime = _load("server_runtime.json")
    if isinstance(runtime, list) and runtime:
        # Prefer most recent row's timezone if present
        try:
            runtime_sorted = sorted(
                [r for r in runtime if isinstance(r, dict)],
                key=lambda r: (r.get("started_at") or r.get("created_at") or ""),
                reverse=True,
            )
            if runtime_sorted and isinstance(runtime_sorted[0].get("timezone"), str) and runtime_sorted[0]["timezone"].strip():
                tz = runtime_sorted[0]["timezone"].strip()
        except Exception:
            pass

    next_run_at = _compute_next_run(schedule, parsed, tz=tz) if status == "active" else None

    # ---------- Insert ----------
    def _new_id(prefix):
        # roughly ULID-like sortable id
        return f"{prefix}_{uuid.uuid4().hex[:26]}".lower()

    task_row = {
        "id": _new_id("tsk"),
        "task_type": "command",
        "name": name.strip(),
        "description": description,
        "schedule": schedule.strip(),
        "enabled": bool(enabled),
        "do_only_once": bool(do_only_once),
        "status": status,
        "command": command,
        "api_url": None,
        "api_method": None,
        "api_headers": None,
        "api_body": None,
        "prompt": None,
        "reminder_title": None,
        "reminder_message": None,
        "next_run_at": next_run_at,
        "last_run_at": None,
        "last_success_at": None,
        "last_error_at": None,
        "last_error_message": None,
        "created_at": now_iso,
        "updated_at": now_iso,
        "deleted_at": None,
    }

    tasks.append(task_row)
    _save("scheduler_tasks.json", tasks)

    _write_log("success", None, None)
    return {"task": task_row}

def add_api_task(name, schedule, api_url, api_method=None, api_headers=None, api_body=None, description=None, enabled=None, do_only_once=None, **_extra):
    import json, os, datetime, time, uuid, re, urllib.parse
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0219000" if __import__("os").path.isdir("./environment_mix/0219000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "add_api_task"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat()
        return None

    def _ensure_logs():
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            return logs
        return []

    def _write_log(status, error_code=None, message=None):
        logs = _ensure_logs()
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": f"req_{int(time.time()*1000)}_{uuid.uuid4().hex[:8]}",
            "endpoint": endpoint,
            "credential_id": None,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": _now().isoformat()
        }
        if message is not None:
            row["message"] = message
        logs.append(row)
        _save("request_logs.json", logs)

    def _is_nonempty_str(v):
        return isinstance(v, str) and bool(v.strip())

    def _parse_schedule(expr):
        if not isinstance(expr, str):
            return _err("VALIDATION_ERROR", "schedule must be a string")
        s = expr.strip()
        if not s:
            return _err("VALIDATION_ERROR", "schedule must be a non-empty string")

        m = re.match(r"^\s*interval\s+(\d+)\s*(seconds|second|minutes|minute|hours|hour|days|day)\s*$", s, re.I)
        if m:
            n = int(m.group(1))
            unit = m.group(2).lower()
            if n <= 0:
