            _write_log("error", sched["error"]["code"], sched["error"]["message"])
            return sched

        tasks = _load("scheduler_tasks.json")
        if not isinstance(tasks, list):
            tasks = []

        # Enforce uniqueness only among non-deleted reminder tasks (avoid false conflicts)
        for t in tasks:
            if isinstance(t, dict) and t.get("status") != "deleted" and t.get("name") == name and t.get("task_type") == "reminder":
                _write_log("error", "CONFLICT", "unique(name) violation")
                return _err("CONFLICT", "A task with the same name already exists for a non-deleted reminder task.", rule="unique(name) WHERE status <> 'deleted'")

        now = _now().isoformat()
        status = "active" if enabled else "disabled"
        next_run_at = None
        if status == "active":
            if sched.get("kind") == "interval":
                next_run_at = _iso(_now() + sched["delta"])
            else:
                next_run_at = _iso(sched.get("next_run_at"))
        if status == "disabled":
            next_run_at = None

        row = {
            "id": f"tsk_{uuid.uuid4().hex}",
            "task_type": "reminder",
            "name": name,
            "description": description,
            "schedule": schedule,
            "enabled": bool(enabled),
            "do_only_once": bool(do_only_once),
            "status": status,
            "command": None,
            "api_url": None,
            "api_method": None,
            "api_headers": None,
            "api_body": None,
            "prompt": None,
            "reminder_title": title,
            "reminder_message": message,
            "next_run_at": next_run_at,
            "last_run_at": None,
            "last_success_at": None,
            "last_error_at": None,
            "last_error_message": None,
            "created_at": now,
            "updated_at": now,
            "deleted_at": None
        }

        tasks.append(row)
        _save("scheduler_tasks.json", tasks)
        _write_log("ok")
        return {"task": row}
    except Exception as e:
        _write_log("error", "VALIDATION_ERROR", "unexpected error")
        return _err("VALIDATION_ERROR", "Unexpected error.", details=str(e))

def update_task(task_id, name=None, schedule=None, command=None, api_url=None, api_method=None, api_headers=None, api_body=None, prompt=None, description=None, enabled=None, do_only_once=None, reminder_title=None, reminder_message=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0219000" if __import__("os").path.isdir("./environment_mix/0219000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    tasks_file = "scheduler_tasks.json"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_cron_or_interval(expr):
        if not isinstance(expr, str):
            return None, "schedule must be a string"
        s = expr.strip()
        if not s:
            return None, "schedule must not be empty"
        low = s.lower()

        m = re.fullmatch(r"every\s+(\d+)\s*(second|seconds|minute|minutes|hour|hours|day|days)\s*", low)
        if m:
            n = int(m.group(1))
            unit = m.group(2)
            if n <= 0:
                return None, "interval must be > 0"
            seconds = n
            if "minute" in unit:
                seconds = n * 60
            elif "hour" in unit:
                seconds = n * 3600
            elif "day" in unit:
                seconds = n * 86400
            nxt = datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(seconds=seconds)
            return nxt, None

        m = re.fullmatch(r"(\d+)\s*([smhd])\s*", low)
        if m:
            n = int(m.group(1))
            if n <= 0:
                return None, "interval must be > 0"
            unit = m.group(2)
            mult = {"s": 1, "m": 60, "h": 3600, "d": 86400}[unit]
            nxt = datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(seconds=n * mult)
            return nxt, None

        parts = s.split()
        if len(parts) == 5:
            ranges = [(0, 59), (0, 23), (1, 31), (1, 12), (0, 6)]
            for i, p in enumerate(parts):
                p = p.strip()
                if p == "*":
                    continue
                m2 = re.fullmatch(r"\*/(\d+)", p)
                if m2:
                    step = int(m2.group(1))
                    if step <= 0:
                        return None, "cron step must be > 0"
                    continue
                if not re.fullmatch(r"\d+", p):
                    return None, "invalid cron field"
                v = int(p)
                lo, hi = ranges[i]
                if v < lo or v > hi:
                    return None, "cron field out of range"
            nxt = datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(minutes=1)
            return nxt, None

        return None, "schedule must be a valid interval (e.g. 'every 5 minutes' or '10m') or 5-field cron"

    # Validate task_id
    if not isinstance(task_id, str) or not task_id.strip():
        return _err("VALIDATION_ERROR", "task_id is required and must be a non-empty string", field="task_id")

    # Validate optional field types/enums (only when not None)
    if name is not None and (not isinstance(name, str) or not name.strip()):
        return _err("VALIDATION_ERROR", "name must be a non-empty string or null", field="name")
    if schedule is not None and (not isinstance(schedule, str) or not schedule.strip()):
        return _err("VALIDATION_ERROR", "schedule must be a non-empty string or null", field="schedule")
    if command is not None and (not isinstance(command, str) or not command.strip()):
        return _err("VALIDATION_ERROR", "command must be a non-empty string or null", field="command")
    if api_url is not None and (not isinstance(api_url, str) or not api_url.strip()):
        return _err("VALIDATION_ERROR", "api_url must be a non-empty string or null", field="api_url")
    if api_method is not None:
        if not isinstance(api_method, str) or not api_method.strip():
            return _err("VALIDATION_ERROR", "api_method must be a non-empty string or null", field="api_method")
        if api_method.upper() not in ["GET", "POST", "PUT", "PATCH", "DELETE", "HEAD", "OPTIONS"]:
            return _err("VALIDATION_ERROR", "api_method is not in allowed enum", field="api_method")
        api_method = api_method.upper()
    if api_headers is not None:
        if not isinstance(api_headers, dict):
            return _err("VALIDATION_ERROR", "api_headers must be an object or null", field="api_headers")
        for k, v in api_headers.items():
            if not isinstance(k, str) or not isinstance(v, str):
                return _err("VALIDATION_ERROR", "api_headers keys and values must be strings", field="api_headers")
    if api_body is not None and not isinstance(api_body, dict):
        return _err("VALIDATION_ERROR", "api_body must be an object or null", field="api_body")
    if prompt is not None and (not isinstance(prompt, str) or not prompt.strip()):
        return _err("VALIDATION_ERROR", "prompt must be a non-empty string or null", field="prompt")
    if description is not None and not isinstance(description, str):
        return _err("VALIDATION_ERROR", "description must be a string or null", field="description")
    if enabled is not None and not isinstance(enabled, bool):
        return _err("VALIDATION_ERROR", "enabled must be a boolean or null", field="enabled")
    if do_only_once is not None and not isinstance(do_only_once, bool):
        return _err("VALIDATION_ERROR", "do_only_once must be a boolean or null", field="do_only_once")
    if reminder_title is not None and not isinstance(reminder_title, str):
        return _err("VALIDATION_ERROR", "reminder_title must be a string or null", field="reminder_title")
    if reminder_message is not None and (not isinstance(reminder_message, str) or not reminder_message.strip()):
        return _err("VALIDATION_ERROR", "reminder_message must be a non-empty string or null", field="reminder_message")

    tasks = _load(tasks_file)
    idx = None
    for i, r in enumerate(tasks):
        if r.get("id") == task_id and r.get("status") != "deleted":
            idx = i
            break
    if idx is None:
        return _err("NOT_FOUND", "task not found", task_id=task_id)

    cur = tasks[idx]
    task_type = cur.get("task_type")

    # Name uniqueness if changing
    if name is not None and name != cur.get("name"):
        for r in tasks:
            if r.get("id") != task_id and r.get("status") != "deleted" and r.get("name") == name:
                return _err("CONFLICT", "a non-deleted task with the same name already exists", field="name")

    # Validate schedule if changing
    computed_next = None
    if schedule is not None and schedule != cur.get("schedule"):
        computed_next, sched_err = _parse_cron_or_interval(schedule)
        if sched_err:
            return _err("VALIDATION_ERROR", sched_err, field="schedule")

    # Ensure no implicit task_type change: reject providing incompatible fields for current type,
    # except that callers may explicitly set incompatible fields to NULL.
    provided = {
        "command": command,
        "api_url": api_url,
        "api_method": api_method,
        "api_headers": api_headers,
        "api_body": api_body,
        "prompt": prompt,
        "reminder_title": reminder_title,
        "reminder_message": reminder_message,
    }

    def _reject_incompatible(field):
        return _err("VALIDATION_ERROR", f"field '{field}' is not applicable for task_type='{task_type}'", field=field, task_type=task_type)

    if task_type == "command":
        for f in ["api_url", "api_method", "api_headers", "api_body", "prompt", "reminder_title", "reminder_message"]:
            if provided[f] is not None:
                return _reject_incompatible(f)
    elif task_type == "api":
        for f in ["command", "prompt", "reminder_title", "reminder_message"]:
            if provided[f] is not None:
                return _reject_incompatible(f)
    elif task_type == "ai":
        for f in ["command", "api_url", "api_method", "api_headers", "api_body", "reminder_title", "reminder_message"]:
            if provided[f] is not None:
                return _reject_incompatible(f)
    elif task_type == "reminder":
        for f in ["command", "api_url", "api_method", "api_headers", "api_body", "prompt"]:
            if provided[f] is not None:
                return _reject_incompatible(f)
    else:
        return _err("VALIDATION_ERROR", "unknown task_type on stored task", task_type=task_type)

    # Apply patch (only non-null fields)
    updated = dict(cur)
    if name is not None:
        updated["name"] = name
    if description is not None:
        updated["description"] = description
    if schedule is not None:
        updated["schedule"] = schedule
    if enabled is not None:
        updated["enabled"] = enabled
    if do_only_once is not None:
        updated["do_only_once"] = do_only_once

    if task_type == "command":
        if command is not None:
            updated["command"] = command
    if task_type == "api":
        if api_url is not None:
            updated["api_url"] = api_url
        if api_method is not None:
            updated["api_method"] = api_method
        if api_headers is not None:
            updated["api_headers"] = api_headers
        if api_body is not None:
            updated["api_body"] = api_body
    if task_type == "ai":
        if prompt is not None:
            updated["prompt"] = prompt
    if task_type == "reminder":
        if reminder_title is not None:
            updated["reminder_title"] = reminder_title
        if reminder_message is not None:
            updated["reminder_message"] = reminder_message

    # Enforce lifecycle/constraints: status/enabled coupling
    status = updated.get("status")
    if updated.get("enabled") is True and status != "active":
        # Since tool doesn't accept explicit status, auto-transition to active when enabling unless illegal
        if status in ("completed", "deleted"):
            return _err("INVALID_TRANSITION", "cannot enable a completed or deleted task", from_status=status, to_status="active")
        # legal transitions: disabled->active, active->active
        updated["status"] = "active"
        status = "active"
    if updated.get("enabled") is False and status == "active":
        # keep status unless explicitly disabled by enable=false (align with constraint: status='disabled' implies enabled=false, but not vice versa)
        # For consistency with disable_task semantics, set to disabled unless already deleted/completed.
        if status not in ("deleted", "completed"):
            updated["status"] = "disabled"
            status = "disabled"
    if status == "disabled" and updated.get("enabled") is not False:
        updated["enabled"] = False

    # Enforce type requirements after update
    if task_type == "command":
        if updated.get("command") is None:
            return _err("VALIDATION_ERROR", "task_type='command' requires command", field="command")
        for f in ["api_url", "prompt", "reminder_message"]:
            if updated.get(f) is not None:
                return _err("VALIDATION_ERROR", "task_type='command' implies api_url/prompt/reminder_message are null")
    if task_type == "api":
        if updated.get("api_url") is None:
            return _err("VALIDATION_ERROR", "task_type='api' requires api_url", field="api_url")
    if task_type == "ai":
        if updated.get("prompt") is None:
            return _err("VALIDATION_ERROR", "task_type='ai' requires prompt", field="prompt")
    if task_type == "reminder":
        if updated.get("reminder_message") is None:
            return _err("VALIDATION_ERROR", "task_type='reminder' requires reminder_message", field="reminder_message")

    # Validate api_headers types if still present
    if updated.get("api_headers") is not None:
        if not isinstance(updated["api_headers"], dict):
            return _err("VALIDATION_ERROR", "api_headers must be an object", field="api_headers")
        for k, v in updated["api_headers"].items():
            if not isinstance(k, str) or not isinstance(v, str):
                return _err("VALIDATION_ERROR", "api_headers keys and values must be strings", field="api_headers")

    # next_run_at behavior
    if status in ("completed", "deleted", "disabled"):
        updated["next_run_at"] = None
    else:
        # status active
        if schedule is not None:
            # we already validated, computed_next may be None if unchanged
            if computed_next is None:
                computed_next, _ = _parse_cron_or_interval(updated["schedule"])
            updated["next_run_at"] = computed_next.isoformat() if computed_next else None
        else:
            # if enabling moved to active from disabled, recompute
            if cur.get("status") == "disabled" and updated.get("status") == "active":
                nxt, err = _parse_cron_or_interval(updated.get("schedule", ""))
                if err:
                    return _err("VALIDATION_ERROR", err, field="schedule")
                updated["next_run_at"] = nxt.isoformat()

    # Update timestamps
    updated["updated_at"] = _now_iso()

    # Write through
    tasks[idx] = updated
    _save(tasks_file, tasks)

    return {"task": updated, "meta": {"latency_ms": int((time.time() - t0) * 1000)}}

def remove_task(task_id, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0219000" if __import__("os").path.isdir("./environment_mix/0219000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    tasks_file = "scheduler_tasks.json"
    exec_file = "task_executions.json"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    if not isinstance(task_id, str) or not task_id.strip():
        return _err("VALIDATION_ERROR", "task_id is required and must be a non-empty string", field="task_id")

    tasks = _load(tasks_file)
    idx = None
    for i, r in enumerate(tasks):
        if r.get("id") == task_id and r.get("status") != "deleted":
            idx = i
            break
    if idx is None:
        return _err("NOT_FOUND", "task not found", task_id=task_id)

    row = dict(tasks[idx])

    # If already soft-deleted, treat as not found (since API says status <> 'deleted' for retrieval)
    if row.get("status") == "deleted":
        return _err("NOT_FOUND", "task not found", task_id=task_id)

    # Enforce transition allowed to deleted
    cur_status = row.get("status")
    allowed = {
        "active": ["disabled", "completed", "deleted"],
        "disabled": ["active", "deleted"],
        "completed": ["deleted"],
        "deleted": [],
    }
    if "deleted" not in allowed.get(cur_status, []):
        return _err("INVALID_TRANSITION", "cannot delete task from current status", from_status=cur_status, to_status="deleted")

    # Soft delete: do not physically delete if executions exist (rule). We'll always soft-delete.
    executions = _load(exec_file)
    has_exec = any(e.get("task_id") == task_id for e in executions)

    now = _now_iso()
    row["status"] = "deleted"
    row["enabled"] = False
    row["deleted_at"] = now
    row["next_run_at"] = None
    row["updated_at"] = now

    tasks[idx] = row
    _save(tasks_file, tasks)

    return {
        "task": row,
        "meta": {
            "had_executions": bool(has_exec),
            "latency_ms": int((time.time() - t0) * 1000)
        }
    }

def enable_task(task_id, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0219000" if __import__("os").path.isdir("./environment_mix/0219000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now().isoformat()

    def _log(endpoint, status, error_code=None, message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "credential_id": None,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": _now_iso()
        }
        if message is not None:
            row["message"] = message
        logs.append(row)
        _save("request_logs.json", logs)

    def _parse_schedule_and_next(expr):
        if not isinstance(expr, str):
            return None, "schedule must be a string"
        s = expr.strip()
        if not s:
            return None, "schedule must be a non-empty string"
        low = s.lower()
        base = _now()

        m = re.fullmatch(r"every\s+(\d+)\s*(seconds|second|minutes|minute|hours|hour|days|day)\s*", low)
        if m:
            n = int(m.group(1))
            if n <= 0:
                return None, "Invalid schedule: interval must be > 0"
            unit = m.group(2)
            mult = 1
            if "minute" in unit:
                mult = 60
            elif "hour" in unit:
                mult = 3600
            elif "day" in unit:
                mult = 86400
            return (base + datetime.timedelta(seconds=n * mult)).isoformat(), None

        m = re.fullmatch(r"(\d+)\s*([smhd])\s*", low)
        if m:
            n = int(m.group(1))
            if n <= 0:
                return None, "Invalid schedule: interval must be > 0"
            mult = {"s": 1, "m": 60, "h": 3600, "d": 86400}[m.group(2)]
            return (base + datetime.timedelta(seconds=n * mult)).isoformat(), None

        cron_expr = s
        if low.startswith("cron "):
            cron_expr = s[5:].strip()
            if not cron_expr:
                return None, "Invalid schedule: missing cron expression after 'cron'"

        parts = cron_expr.split()
        if len(parts) != 5:
            return None, "Invalid schedule: Invalid schedule format (expected 'every N unit', 'Ns|Nm|Nh|Nd', or cron with 5 fields; optional 'cron ' prefix)."

        name_map = {"sun": 0, "mon": 1, "tue": 2, "wed": 3, "thu": 4, "fri": 5, "sat": 6}
        ranges = [(0, 59), (0, 23), (1, 31), (1, 12), (0, 7)]
        def _parse_token(tok, idx):
            tok = tok.strip().lower()
            if tok in name_map and idx == 4:
                return True, None
            if tok == "*":
                return True, None
            if re.fullmatch(r"\*/\d+", tok):
                step = int(tok.split("/")[1])
                if step <= 0:
                    return False, "cron step must be > 0"
                return True, None
            if re.fullmatch(r"\d+", tok):
                v = int(tok); lo, hi = ranges[idx]
                if v < lo or v > hi:
                    return False, f"cron field out of range ({lo}-{hi})"
                return True, None
            m2 = re.fullmatch(r"(\d+)-(\d+)(/\d+)?", tok)
            if m2:
                a = int(m2.group(1)); b = int(m2.group(2))
                lo, hi = ranges[idx]
                if a < lo or a > hi or b < lo or b > hi or a > b:
                    return False, f"cron range out of range ({lo}-{hi})"
                if m2.group(3):
                    step = int(m2.group(3)[1:])
                    if step <= 0:
                        return False, "cron step must be > 0"
                return True, None
            return False, "Invalid cron field token"

        for idx, field in enumerate(parts):
            items = field.split(",")
            if any(it.strip() == "" for it in items):
                return None, "Invalid schedule: Invalid cron field token"
            for it in items:
                ok, em = _parse_token(it, idx)
                if not ok:
                    return None, f"Invalid schedule: {em}"

        return (base + datetime.timedelta(seconds=60)).isoformat(), None

    endpoint = "enable_task"
    if not isinstance(task_id, str) or not task_id.strip():
        _log(endpoint, "error", "VALIDATION_ERROR", "task_id type")
        return _err("VALIDATION_ERROR", "task_id must be a non-empty string")

    tasks = _load("scheduler_tasks.json")
    if isinstance(tasks, dict) and "rows" in tasks and isinstance(tasks["rows"], list):
        tasks_rows = tasks["rows"]
        tasks_is_wrapped = True
    elif isinstance(tasks, list):
        tasks_rows = tasks
        tasks_is_wrapped = False
    else:
        tasks_rows = []
        tasks_is_wrapped = False

    task = None
    idx = None
    for i, r in enumerate(tasks_rows):
        if isinstance(r, dict) and r.get("id") == task_id:
            task = r
            idx = i
            break

    if task is None or task.get("status") == "deleted":
        _log(endpoint, "error", "NOT_FOUND", "task not found")
        return _err("NOT_FOUND", "Task not found")

    # Enable policy: reject completed or deleted
    if task.get("status") == "completed":
        _log(endpoint, "error", "INVALID_TRANSITION", "cannot enable completed")
        return _err("INVALID_TRANSITION", "Cannot enable a completed task.")
    if task.get("status") == "deleted":
        _log(endpoint, "error", "INVALID_TRANSITION", "cannot enable deleted")
        return _err("INVALID_TRANSITION", "Cannot enable a deleted task.")

    next_run_at, sch_err = _parse_schedule_and_next(task.get("schedule"))
    if sch_err:
        _log(endpoint, "error", "VALIDATION_ERROR", sch_err)
        return _err("VALIDATION_ERROR", sch_err)

    # Lifecycle transitions: disabled->active allowed; active->active allowed (idempotent)
    cur = task.get("status")
    if cur not in ("active", "disabled"):
        _log(endpoint, "error", "INVALID_TRANSITION", "bad state")
        return _err("INVALID_TRANSITION", f"Cannot enable task from status '{cur}'.")

    now_iso = _now_iso()
    task["enabled"] = True
    task["status"] = "active"
    task["next_run_at"] = next_run_at
    task["updated_at"] = now_iso
    # ensure completed/deleted rules
    task["deleted_at"] = task.get("deleted_at")

    tasks_rows[idx] = task
    if tasks_is_wrapped:
        tasks["rows"] = tasks_rows
        _save("scheduler_tasks.json", tasks)
    else:
        _save("scheduler_tasks.json", tasks_rows)

    _log(endpoint, "ok", None, None)
    return {"task": task}

def disable_task(task_id, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0219000" if __import__("os").path.isdir("./environment_mix/0219000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(endpoint, status, task_id=None, extra=None):
        fname = "request_logs.json"
        path = os.path.join(_DB, fname)
        if not os.path.exists(path):
            return
        logs = _load(fname)
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status,
            "task_id": task_id,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save(fname, logs)

    if not isinstance(task_id, str) or not task_id.strip():
        _log("disable_task", "error", task_id=str(task_id) if task_id is not None else None, extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "task_id must be a non-empty string")

    tasks = _load("scheduler_tasks.json")
    task = next((r for r in tasks if r.get("id") == task_id and r.get("status") != "deleted"), None)
    if not task:
        _log("disable_task", "error", task_id=task_id, extra={"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Task not found")

    status = task.get("status")
    if status == "deleted":
        _log("disable_task", "error", task_id=task_id, extra={"error_code": "CONFLICT"})
        return _err("CONFLICT", "Task is deleted and cannot be disabled")
    if status == "completed":
        # Business rules only called out enable restriction; disabling completed doesn't make sense—treat as conflict.
        _log("disable_task", "error", task_id=task_id, extra={"error_code": "CONFLICT"})
        return _err("CONFLICT", "Task is completed and cannot be disabled")

    if status not in ("active", "disabled"):
        _log("disable_task", "error", task_id=task_id, extra={"error_code": "INVALID_TRANSITION"})
        return _err("INVALID_TRANSITION", f"Illegal status '{status}' for disable operation")

    # Apply changes (idempotent if already disabled)
    task["enabled"] = False
    task["status"] = "disabled"
    task["next_run_at"] = None
    task["updated_at"] = now

    _save("scheduler_tasks.json", tasks)
    _log("disable_task", "ok", task_id=task_id)
    return {"task": task}

def get_task_executions(task_id, limit=10, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0219000" if __import__("os").path.isdir("./environment_mix/0219000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(endpoint, status, task_id=None, extra=None):
        fname = "request_logs.json"
        path = os.path.join(_DB, fname)
        if not os.path.exists(path):
            return
        logs = _load(fname)
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status,
            "task_id": task_id,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save(fname, logs)

    if not isinstance(task_id, str) or not task_id.strip():
        _log("get_task_executions", "error", task_id=str(task_id) if task_id is not None else None, extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "task_id must be a non-empty string")

    if limit is None:
        limit = 10
    if not isinstance(limit, int):
        _log("get_task_executions", "error", task_id=task_id, extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1:
        _log("get_task_executions", "error", task_id=task_id, extra={"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "limit must be a positive integer")
    if limit > 100:
        limit = 100  # constrain to 1..100 per business rules

    tasks = _load("scheduler_tasks.json")
    task = next((r for r in tasks if r.get("id") == task_id and r.get("status") != "deleted"), None)
    if not task:
        _log("get_task_executions", "error", task_id=task_id, extra={"error_code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Task not found")

    executions = _load("task_executions.json")
    rows = [r for r in executions if r.get("task_id") == task_id]

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    rows.sort(key=lambda r: _parse_dt(r.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), reverse=True)
    out = rows[:limit]

    _log("get_task_executions", "ok", task_id=task_id, extra={"returned": len(out)})
    return {
        "executions": out,
        "limit": limit,
        "total": len(rows),
    }

def get_server_info(instance_id=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0219000" if __import__("os").path.isdir("./environment_mix/0219000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    # --- Load runtime rows ---
    runtime = _load("server_runtime.json")
    if not isinstance(runtime, list):
        runtime = []

    # --- Input validation ---
    if instance_id is not None:
        if not isinstance(instance_id, str):
            return _err("VALIDATION_ERROR", "instance_id must be a string")
        iid = instance_id.strip()
        if iid == "":
            return _err("VALIDATION_ERROR", "instance_id must be a non-empty identifier")
        # conservative "identifier" validation (letters/digits/._- and reasonable length)
        if len(iid) > 200 or re.search(r"[^A-Za-z0-9._-]", iid):
            return _err("VALIDATION_ERROR", "instance_id is not a valid identifier")
        instance_id = iid

    # --- AuthZ (ambient) ---
    # This datastore has no identities/roles/permissions collection; per contract we must not
    # refuse a well-formed request due to missing auth params. We therefore treat access as allowed.

    # --- Filter / select latest row per instance ---
    def _parse_dt(v):
        if not isinstance(v, str) or not v:
            return None
        try:
            # Accept trailing Z
            if v.endswith("Z"):
                v = v[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(v)
        except Exception:
            return None

    latest_by_instance = {}
    for row in runtime:
        if not isinstance(row, dict):
            continue
        iid = row.get("instance_id")
        if not isinstance(iid, str) or not iid:
            continue
        # prefer most recently updated_at, else created_at, else keep first seen
        key_dt = _parse_dt(row.get("updated_at")) or _parse_dt(row.get("created_at"))
        prev = latest_by_instance.get(iid)
        if prev is None:
            latest_by_instance[iid] = row
        else:
            prev_dt = _parse_dt(prev.get("updated_at")) or _parse_dt(prev.get("created_at"))
            if prev_dt is None and key_dt is not None:
                latest_by_instance[iid] = row
            elif prev_dt is not None and key_dt is not None and key_dt > prev_dt:
                latest_by_instance[iid] = row

    if instance_id is not None:
        row = latest_by_instance.get(instance_id)
        if row is None:
            return _err("NOT_FOUND", "No such instance_id is known", instance_id=instance_id)
        result_rows = [row]
    else:
        # Return all instances' latest rows, sorted by started_at desc then instance_id asc
        def _sort_key(r):
            sdt = _parse_dt(r.get("started_at")) or _parse_dt(r.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            return (-int(sdt.timestamp()) if sdt.tzinfo else 0, str(r.get("instance_id", "")))
        result_rows = sorted(latest_by_instance.values(), key=_sort_key)

    latency_ms = int((time.time() - t0) * 1000)

    # Ensure schema-required fields are present as stored; do not fabricate.
    return {
        "data": result_rows,
        "meta": {
            "count": len(result_rows),
            "filtered_by_instance_id": instance_id is not None,
            "instance_id": instance_id,
            "latency_ms": latency_ms,
            "timestamp": now_iso,
        },
    }
